#define TWOPI 6.283185307179586
#define SQRT3 1.7320508075688772
// speed of migration of the centers
#define SPEED 30.0
// number of regions
#define NUM_CELLS 30.0
// offset from the random texture
#define SEED 0.0
// thickness of the borders of each region (in pixels)
#define THICKNESS 4.0
// inclination of the indents at the edges
#define INCLINE 0.8
// window size
#define WINDOW 25.0

// isometric
const vec2 base0 = vec2(-SQRT3,1)/2.0;
const vec2 base1 = vec2(0,-1);
const vec2 base2 = vec2(SQRT3,1)/2.0;

/* different base example
const vec2 base0 = normalize(vec2(-1,1));
const vec2 base1 = vec2(0,-1);
const vec2 base2 = vec2(1,0);
*/
vec2 likeMod(vec2 dif,vec2 res) {
    return mod(mod(dif+res*0.5,res)+res,res)-res*0.5;
}

float metric(vec2 vetor) {
    return max(max(dot(vetor,base0),dot(vetor,base1)),dot(vetor,base2));//dot(abs(vetor),vec2(1));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec3 closest = vec3(10.0*iResolution.xy,-1);
    vec3 second = closest;
    for (float i = 0.0; i < NUM_CELLS; i++) {
        vec4 rng = texelFetch(iChannel0,ivec2(mod(i+SEED,iChannelResolution[0].x),mod((i+SEED)/iChannelResolution[0].x,iChannelResolution[0].y)),0);
        vec3 nuc = vec3(iResolution.xy*rng.xy,i);
        nuc += SPEED*iTime*vec3(cos(TWOPI*rng.z),sin(TWOPI*rng.z),0); // movement
        nuc = vec3(likeMod(nuc.xy-fragCoord,iResolution.xy)+fragCoord,i); //this line makes it tileable
        if (metric(nuc.xy-fragCoord) < metric(closest.xy-fragCoord)) {
            second = closest;
            closest = nuc;
        } else if (metric(nuc.xy-fragCoord) < metric(second.xy-fragCoord)) {
            second = nuc;
        }
    }

    float rng = texelFetch(iChannel1,ivec2(mod(closest.z+SEED,iChannelResolution[1].x),mod((closest.z+SEED)/iChannelResolution[1].x,iChannelResolution[1].y)),0).r;
    if (rng <= 0.5) {
        fragColor = vec4(.32,.03,.32,1)*(1.0-rng*2.0) + vec4(.7,.3,.7,1)*rng*2.0;
    } else {
        fragColor = vec4(.7,.3,.7,1)*(2.0-rng*2.0) + vec4(.84,.56,.84,1)*(rng*2.0-1.0);
    }

    float angle;// = floor(3.0*atan(closest.x-fragCoord.x,-closest.y+fragCoord.y)/TWOPI + 1.5);
    if (metric(closest.xy-fragCoord) == dot(closest.xy-fragCoord,base0))
        angle = 0.0;
    else if (metric(closest.xy-fragCoord) == dot(closest.xy-fragCoord,base1))
        angle = 1.0;
    else
        angle = 2.0;

    vec2 parede;
    if (angle == 0.0) {
        parede = fract( inverse(mat2(normalize(base0+base1),normalize(base0+base2)))*(fragCoord-closest.xy)/WINDOW );
    } else if (angle == 2.0) {
        parede = fract( inverse(mat2(normalize(base2+base1),normalize(base0+base2)))*(fragCoord-closest.xy)/WINDOW );
    }
    if (angle != 1.0) {
        if ((int(rng*256.0)&3) == 0) {
            // window type 0
            if (abs(parede.x-0.5) < 0.11 && abs(parede.y-0.45) < 0.15)
                fragColor = vec4(0,0,0,1);
            else if (abs(parede.x-0.5) < 0.16 && abs(parede.y-0.45) < 0.2)
                fragColor = vec4(1);
        } else if ((int(rng*256.0)&3) == 1) {
            // window type 1
            if (abs(parede.x-0.5) < 0.15 && abs(parede.y-0.5) < 0.17) {
                if (abs(parede.x-0.5) < 0.02 || abs(parede.y-0.5) < 0.03)
                    fragColor = vec4(1);
                else
                    fragColor = vec4(0,0,0,1);
            } else if (abs(parede.x-0.5) < 0.2 && abs(parede.y-0.5) < 0.22)
                fragColor = vec4(1);
        } else if ((int(rng*256.0)&3) == 2) {
            // window type 2
            if (abs(parede.x-0.5) < 0.15 && abs(parede.y-0.5) < 0.22) {
                if (abs(parede.y-0.5) < 0.03)
                    fragColor = vec4(1);
                else
                    fragColor = vec4(0,0,0,1);
            } else if (abs(parede.x-0.5) < 0.2 && abs(parede.y-0.5) < 0.27)
                fragColor = vec4(1);
        } else if ((int(rng*256.0)&3) == 3) {
            // window type 3
            if (abs(parede.x-0.5) < 0.2 && abs(parede.y-0.5) < 0.17) {
                if (abs(parede.x-0.5) < 0.03)
                    fragColor = vec4(1);
                else
                    fragColor = vec4(0,0,0,1);
            } else if (abs(parede.x-0.5) < 0.25 && abs(parede.y-0.5) < 0.22)
                fragColor = vec4(1);
        }
    }
    fragColor.xyz *= (angle+3.0)/5.0;
}
